use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " Result of a (potentially partial) decode or encode operation with"] # [doc = " replacement."] # [must_use] # [derive (Debug , PartialEq , Eq)] pub enum CoderResult { # [doc = " The input was exhausted."] # [doc = ""] # [doc = " If this result was returned from a call where `last` was `true`, the"] # [doc = " conversion process has completed. Otherwise, the caller should call a"] # [doc = " decode or encode method again with more input."] InputEmpty , # [doc = " The converter cannot produce another unit of output, because the output"] # [doc = " buffer does not have enough space left."] # [doc = ""] # [doc = " The caller must provide more output space upon the next call and re-push"] # [doc = " the remaining input to the converter."] OutputFull , }